/** Crockford base32, minus I, L, O and U. */
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const TIME_LENGTH = 10;
const RANDOM_LENGTH = 16;

const ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;

