/**
 * Personal API tokens: issue, list, revoke, and authenticate. The secret is
 * returned once from `createApiToken` and only its hash is persisted.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hashToken, randomToken
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as tokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { envelope, orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const TOKEN_PREFIX = "tfk_";
const PREFIX_LENGTH = 12;
const MAX_USABLE_TOKENS = 5;
const DAY_MS = 24 * 60 * 60 * 1000;

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(parsed.orgId));
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  const usable = await tokenRepo.countUsableTokens(parsed.orgId, actor.userId, createdAt);
  if (usable >= MAX_USABLE_TOKENS) {
    throw new Error(
      `A user may hold at most ${MAX_USABLE_TOKENS} active API tokens per organization`,
    );
  }

  const token = `${TOKEN_PREFIX}${randomToken()}`;
  const apiToken = await tokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    prefix: token.slice(0, PREFIX_LENGTH),
    tokenHash: hashToken(token),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + parsed.expiresInDays * DAY_MS)),
    createdAt,
  });

  await emit("api_token.created", {
    ...envelope(apiToken.orgId, actor.userId),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  const target = userId ?? actor.userId;
  if (target !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }
  return tokenRepo.listTokensForUser(orgId, target);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const existing = requireFound(
    await tokenRepo.findTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  return (await revokeAndAudit(existing, actor.userId)) ?? existing;
}

async function revokeAndAudit(
  token: ApiToken,
  actorId: UserId | null,
): Promise<ApiToken | null> {
  const revoked = await tokenRepo.revokeToken(
    token.orgId,
    token.id,
    toIsoTimestamp(new Date()),
  );
  if (!revoked) return null;

  await emit("api_token.revoked", {
    ...envelope(revoked.orgId, actorId),
    tokenId: revoked.id,
    userId: revoked.userId,
    name: revoked.name,
  });
  return revoked;
}

export async function authenticateApiToken(token: string): Promise<Actor | null> {
  if (typeof token !== "string" || token.length === 0) return null;

  const found = await tokenRepo.findTokenByHash(hashToken(token));
  if (!found || found.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (now >= found.expiresAt) return null;

  const org = await orgRepo.findOrgById(found.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(found.orgId, found.userId);
  if (!member || member.status !== "active") return null;

  await tokenRepo.touchLastUsed(found.orgId, found.id, now);

  return {
    userId: found.userId,
    orgId: found.orgId,
    role: found.scope === "read" ? "viewer" : member.role,
  };
}

/** Revokes a removed member's tokens in that organization. */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await tokenRepo.listUnrevokedTokensForUser(
      payload.orgId,
      payload.userId,
    );
    for (const token of tokens) {
      await revokeAndAudit(token, payload.actorId);
    }
  });
}
